// GetCurrentProcessToken: Retrieves a pseudo-handle that you can use as a shorthand way to refer to the access token
// associated with a process.
func GetCurrentProcessToken() uintptr {
	return ^uintptr(3)
}

// GetCurrentThreadEffectiveToken: Retrieves a pseudo-handle that you can use as a shorthand way to refer to the token
// that is currently in effect for the thread, which is the thread token if one exists and the process token otherwise.
func GetCurrentThreadEffectiveToken() uintptr {
	return ^uintptr(5)
}

// GetCurrentThreadToken: Retrieves a pseudo-handle that you can use as a shorthand way to refer to the impersonation
// token that was assigned to the current thread.
func GetCurrentThreadToken() uintptr {
	return ^uintptr(4)
}

